<?php
namespace Tests\Feature;
use App\Models\{BookingServis,JenisServis,RiwayatStok,Servis,ServisSparepart,Sparepart,Transaksi,User}; use App\Services\{BookingServisService,ServisService,ServisSparepartService}; use Illuminate\Foundation\Testing\DatabaseTransactions; use RuntimeException; use Tests\TestCase;
class ServisFinalizationStage5CTest extends TestCase { use DatabaseTransactions;
 private function user(string $r):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$r))->firstOrFail();}
 private function service():Servis{$u=$this->user('pelanggan');$v=$u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Finalize','nomor_polisi'=>'FN-'.random_int(1000,9999),'kilometer'=>40000,'status'=>'aktif']);$t=JenisServis::where('status','aktif')->firstOrFail();$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'13:00',null,null);$b->forceFill(['status'=>'diterima'])->save();$s=app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);app(ServisService::class)->updateInspection($s->id_servis,'Diagnosis',null);return $s->fresh();}
 private function part(Servis $s,int $qty=1):ServisSparepart{return app(ServisSparepartService::class)->add($s->id_servis,1,$qty);}
 public function test_transaction_baseline_is_imported_without_side_effects():void{$this->assertSame(7,Transaksi::count());$this->assertDatabaseHas('transaksi',['id_transaksi'=>4,'jenis_transaksi'=>'servis','status'=>'lunas']);$this->assertSame(5,(int)Sparepart::find(1)->stok);}
 public function test_finalize_without_sparepart_creates_unpaid_transaction():void{$s=$this->service();$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame('servis',$tx->jenis_transaksi);$this->assertSame('belum_bayar',$tx->status);$this->assertSame('dikerjakan',$s->fresh()->status);$this->assertSame('diproses',$s->bookingServis->fresh()->status);$this->assertSame('0.00',$tx->total);}
 public function test_finalize_one_sparepart_consumes_stock_and_history():void{$s=$this->service();$this->part($s,2);$before=RiwayatStok::count();$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame(3,(int)Sparepart::find(1)->fresh()->stok);$this->assertSame($before+1,RiwayatStok::count());$this->assertDatabaseHas('riwayat_stok',['id_sparepart'=>1,'jenis_transaksi'=>'servis','jumlah_perubahan'=>-2,'stok_sebelum'=>5,'stok_sesudah'=>3,'referensi_tipe'=>'servis','referensi_id'=>$s->id_servis]);$this->assertSame($tx->id_transaksi,$s->fresh()->id_transaksi);}
 public function test_totals_use_service_details_and_snapshot_price():void{$s=$this->service();app(ServisService::class)->addDetail($s->id_servis,null,'Jasa','125000',null);$this->part($s,1);$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame('160000.00',$tx->total);$this->assertSame('125000.00',$s->fresh()->biaya_jasa);$this->assertSame('35000.00',$s->fresh()->biaya_sparepart);}
 public function test_actual_stock_is_revalidated_at_finalize():void{$s=$this->service();$this->part($s,4);Sparepart::whereKey(1)->update(['stok'=>2]);$this->expectException(RuntimeException::class);app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame(2,(int)Sparepart::find(1)->fresh()->stok);$this->assertNull($s->fresh()->id_transaksi);}
 public function test_second_sparepart_failure_rolls_back_first_mutation():void{$s=$this->service();$this->part($s,2);$p=Sparepart::create(['kode_sparepart'=>'QA-'.random_int(1000,9999),'id_kategori'=>Sparepart::first()->id_kategori,'nama_sparepart'=>'Part B','harga_beli'=>1,'harga_jual'=>5000,'satuan'=>'pcs','status'=>'aktif']);$p->forceFill(['stok'=>5,'stok_minimum'=>0])->save();app(ServisSparepartService::class)->add($s->id_servis,$p->id_sparepart,2);$p->forceFill(['stok'=>1])->save();$this->expectException(RuntimeException::class);app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame(5,(int)Sparepart::find(1)->fresh()->stok);$this->assertSame(1,(int)$p->fresh()->stok);$this->assertNull($s->fresh()->id_transaksi);}
 public function test_failure_before_commit_rolls_back_stock_history_transaction_and_link():void{$s=$this->service();$this->part($s,1);$beforeHistory=RiwayatStok::count();$beforeTx=Transaksi::count();$this->expectException(RuntimeException::class);try{app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas,fn()=>throw new RuntimeException('simulated'));}finally{$this->assertSame(5,(int)Sparepart::find(1)->fresh()->stok);$this->assertSame($beforeHistory,RiwayatStok::count());$this->assertSame($beforeTx,Transaksi::count());$this->assertNull($s->fresh()->id_transaksi);}}
 public function test_double_finalize_is_rejected_without_duplicate_effects():void{$s=$this->service();$this->part($s,1);$svc=app(ServisService::class);$tx=$svc->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$history=RiwayatStok::count();$count=Transaksi::count();$this->expectException(RuntimeException::class);try{$svc->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);}finally{$this->assertSame(4,(int)Sparepart::find(1)->fresh()->stok);$this->assertSame($history,RiwayatStok::count());$this->assertSame($count,Transaksi::count());$this->assertSame($tx->id_transaksi,$s->fresh()->id_transaksi);}}
 public function test_transaction_code_is_server_generated_and_unique():void{$s=$this->service();$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertMatchesRegularExpression('/^TRX-\d{6}-[A-F0-9]{8}$/',$tx->kode_transaksi);$this->assertNotEmpty($tx->kode_transaksi);}
 public function test_admin_and_petugas_can_finalize_but_customer_cannot():void{$s=$this->service();$this->actingAs($this->user('admin'))->post('/admin/servis/'.$s->id_servis.'/finalize')->assertRedirect();$s2=$this->service();$this->actingAs($this->user('pelanggan'))->post('/pelanggan/servis/'.$s2->id_servis.'/finalize')->assertNotFound();}
 public function test_finalized_draft_and_detail_are_locked():void{$s=$this->service();$item=$this->part($s,1);app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->expectException(RuntimeException::class);app(ServisSparepartService::class)->remove($s->id_servis,$item->id_servis_sparepart);}
 public function test_transaction_relationship_links_both_directions():void{$s=$this->service();$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame($tx->id_transaksi,$s->fresh()->transaksi->id_transaksi);$this->assertSame($s->id_servis,$tx->fresh()->servis->id_servis);}
 public function test_no_payment_is_created_or_required():void{$s=$this->service();app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertTrue(\Illuminate\Support\Facades\Schema::hasTable('pembayaran'));$this->assertSame(0,\App\Models\Pembayaran::where('id_transaksi',$s->fresh()->id_transaksi)->count());}
 public function test_invalid_status_is_rejected():void{$s=$this->service();$s->forceFill(['status'=>'pemeriksaan'])->save();$this->expectException(RuntimeException::class);app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);}
 public function test_snapshot_price_is_used_after_master_price_changes():void{$s=$this->service();$item=$this->part($s,1);$master=Sparepart::findOrFail(1);$master->forceFill(['harga_jual'=>999999])->save();$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame('35000.00',$item->fresh()->harga_satuan);$this->assertSame('35000.00',$tx->total);}
 public function test_finalization_does_not_change_booking_to_done():void{$s=$this->service();app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame('diproses',$s->bookingServis->fresh()->status);}
 public function test_finalized_service_cannot_add_detail():void{$s=$this->service();app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->expectException(RuntimeException::class);app(ServisService::class)->addDetail($s->id_servis,null,'Blocked','10',null);}
 public function test_total_discount_is_zero_and_not_request_driven():void{$s=$this->service();$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame('0.00',$tx->diskon);$this->assertSame('0.00',$tx->total);}
 public function test_transaksi_has_one_service_link():void{$s=$this->service();$tx=app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame(1,Transaksi::where('id_transaksi',$tx->id_transaksi)->where('jenis_transaksi','servis')->count());$this->assertSame(1,Servis::where('id_transaksi',$tx->id_transaksi)->count());}
 public function test_finalize_does_not_create_payment_record():void{$s=$this->service();$before=Transaksi::count();app(ServisService::class)->finalizeService($s->id_servis,$this->user('petugas')->petugas->id_petugas);$this->assertSame($before+1,Transaksi::count());$this->assertTrue(\Illuminate\Support\Facades\Schema::hasTable('pembayaran'));$this->assertSame(0,\App\Models\Pembayaran::where('id_transaksi',$s->fresh()->id_transaksi)->count());}
 public function test_service_transaction_uses_petugas_actor():void{$s=$this->service();$actor=$this->user('petugas')->petugas->id_petugas;$tx=app(ServisService::class)->finalizeService($s->id_servis,$actor);$this->assertSame($actor,$tx->id_petugas);}
}
